<!doctype html><html lang="id"><head><meta name="viewport" content="width=device-width, initial-scale=1"><script src="https://challenges.cloudflare.com/turnstile/v0/api.js" async defer></script><style>body{margin:0;background:#fff;font-family:Arial,sans-serif}.box{padding:18px}p{font-size:14px;color:#172A24}</style></head><body><div class="box"><p>Verifikasi keamanan</p><div class="cf-turnstile" data-sitekey="{{ config('services.turnstile.site_key') }}" data-size="flexible" data-callback="done"></div></div><script>function done(token){if(window.Turnstile){Turnstile.postMessage(token)}else if(window.webkit&&window.webkit.messageHandlers.Turnstile){window.webkit.messageHandlers.Turnstile.postMessage(token)}}</script></body></html>
